/* eslint-disable */
// Generated by scripts/build-sw.mjs. The worker installs an all-or-nothing
// explicit child/read-only shell and never caches API or mutation responses.
const BUILD_ID = '__BUILD_ID__';
const PRECACHE = __PRECACHE__;
const CAPABILITY_MANIFEST = __CAPABILITY_MANIFEST__;
const STATIC_CACHE = 'harjutaja-static-' + BUILD_ID;
const SHELL_CACHE = 'harjutaja-shell-' + BUILD_ID;
const COMPLETE_MARKER = '/__offline-cache-complete__';
const SHELL_ROUTES = CAPABILITY_MANIFEST.shellRoutes;
const PUBLIC_ASSETS = CAPABILITY_MANIFEST.publicAssets;
const ALLOWED_SHELL_PATHS = new Set(SHELL_ROUTES);
const ALLOWED_STATIC_PATHS = new Set([...PRECACHE, ...PUBLIC_ASSETS]);

function sameOrigin(response) {
  try { return new URL(response.url).origin === self.location.origin; } catch { return false; }
}

function validResponse(response, expectedPath, kind) {
  if (!response || !response.ok || response.type === 'opaque' || !sameOrigin(response)) return false;
  const finalUrl = new URL(response.url);
  if (finalUrl.pathname !== expectedPath) return false; // reject auth/error redirects
  const type = response.headers.get('content-type') || '';
  if (kind === 'shell') return type.includes('text/html');
  if (expectedPath.endsWith('.webmanifest')) return type.includes('json') || type.includes('manifest');
  if (/\.(?:png|jpg|jpeg|svg|webp)$/.test(expectedPath)) return type.startsWith('image/');
  if (/\.(?:woff2?|ttf|otf)$/.test(expectedPath)) return type.includes('font') || type.includes('octet-stream');
  if (expectedPath.endsWith('.json')) return type.includes('json');
  return expectedPath.startsWith('/_next/static/') && (type.includes('javascript') || type.includes('css'));
}

// HTML references build-specific hashed chunks, so a shell is only usable by
// the worker of the build that rendered it. The server stamps every page with
// X-App-Build-Id (src/middleware.ts).
const BUILD_ID_HEADER = 'x-app-build-id';

function shellBuildId(response) {
  return response.headers.get(BUILD_ID_HEADER);
}

async function fetchRequired(cache, path, kind) {
  const response = await fetch(path, { credentials: 'same-origin', cache: 'reload', redirect: 'follow' });
  if (!validResponse(response, path, kind)) throw new Error('Required offline resource failed validation: ' + path);
  // A deploy during install would otherwise store another build's HTML. A
  // missing header (a server built without an id) keeps the old behaviour.
  if (kind === 'shell' && shellBuildId(response) !== null && shellBuildId(response) !== BUILD_ID) {
    throw new Error('Offline shell belongs to another build: ' + path);
  }
  await cache.put(path, response.clone());
}

async function cacheStatus(buildId = BUILD_ID) {
  const staticCache = await caches.open('harjutaja-static-' + buildId);
  const shellCache = await caches.open('harjutaja-shell-' + buildId);
  const missingAssets = [];
  for (const path of PRECACHE) if (!(await staticCache.match(path))) missingAssets.push(path);
  for (const path of PUBLIC_ASSETS) if (!(await staticCache.match(path))) missingAssets.push(path);
  for (const path of SHELL_ROUTES) if (!(await shellCache.match(path))) missingAssets.push(path);
  const marker = await shellCache.match(COMPLETE_MARKER);
  let markerBody = null;
  try { markerBody = marker ? await marker.json() : null; } catch { markerBody = null; }
  const cacheComplete = Boolean(markerBody && markerBody.buildId === buildId && markerBody.manifestVersion === CAPABILITY_MANIFEST.manifestVersion && missingAssets.length === 0);
  return { cacheComplete, missingAssets, installedAt: markerBody?.installedAt || null };
}

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const staticCache = await caches.open(STATIC_CACHE);
    const shellCache = await caches.open(SHELL_CACHE);
    // Any missing/redirected/invalid required response rejects installation. A
    // complete marker is written only after every item has been verified.
    for (const path of PRECACHE) await fetchRequired(staticCache, path, 'static');
    for (const path of PUBLIC_ASSETS) await fetchRequired(staticCache, path, 'asset');
    for (const path of SHELL_ROUTES) await fetchRequired(shellCache, path, 'shell');
    await shellCache.put(COMPLETE_MARKER, new Response(JSON.stringify({
      buildId: BUILD_ID,
      manifestVersion: CAPABILITY_MANIFEST.manifestVersion,
      installedAt: new Date().toISOString()
    }), { headers: { 'Content-Type': 'application/json' } }));
  })());
});

async function completeBuilds() {
  const keys = await caches.keys();
  const buildIds = [...new Set(keys.filter((key) => key.startsWith('harjutaja-shell-')).map((key) => key.slice('harjutaja-shell-'.length)))];
  const builds = [];
  for (const id of buildIds) {
    const cache = await caches.open('harjutaja-shell-' + id);
    const marker = await cache.match(COMPLETE_MARKER);
    if (!marker) continue;
    try {
      const body = await marker.json();
      if (body.buildId === id) builds.push({ id, installedAt: Date.parse(body.installedAt) || 0 });
    } catch { /* partial cache; cleaned below */ }
  }
  return builds.sort((a, b) => b.installedAt - a.installedAt);
}

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const complete = await completeBuilds();
    const keep = new Set([...new Set([BUILD_ID, ...complete.map((entry) => entry.id)])].slice(0, 2));
    const keys = await caches.keys();
    await Promise.all(keys.filter((key) => {
      if (!key.startsWith('harjutaja-static-') && !key.startsWith('harjutaja-shell-')) return false;
      const prefix = key.startsWith('harjutaja-static-') ? 'harjutaja-static-' : 'harjutaja-shell-';
      return !keep.has(key.slice(prefix.length));
    }).map((key) => caches.delete(key)));
    await self.clients.claim();
  })());
});

// Updates remain waiting until the UI confirms there is no active runner.
self.addEventListener('message', (event) => {
  const data = event.data;
  if (data === 'SKIP_WAITING' || data?.type === 'SKIP_WAITING') {
    self.skipWaiting();
    return;
  }
  if (data?.type === 'OFFLINE_STATUS_REQUEST') {
    event.waitUntil((async () => {
      const status = await cacheStatus();
      const payload = {
        type: 'OFFLINE_STATUS',
        requestId: data.requestId,
        buildId: BUILD_ID,
        manifestVersion: CAPABILITY_MANIFEST.manifestVersion,
        cacheComplete: status.cacheComplete,
        missingAssets: status.missingAssets
      };
      if (event.ports?.[0]) event.ports[0].postMessage(payload);
      else event.source?.postMessage(payload);
    })());
  }
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin || url.pathname.startsWith('/api/')) return;

  if (request.mode === 'navigate') {
    event.respondWith((async () => {
      let response;
      try {
        response = await fetch(request);
      } catch {
        response = null;
      }
      if (response) {
        // Refresh the shell only with HTML from this worker's own build: while
        // a new worker waits, the server already renders the new build, whose
        // chunks this worker's static cache does not hold (no hydration
        // offline). The copy is stored in the background so the page streams.
        if (
          ALLOWED_SHELL_PATHS.has(url.pathname) &&
          validResponse(response, url.pathname, 'shell') &&
          shellBuildId(response) === BUILD_ID
        ) {
          const copy = response.clone();
          event.waitUntil(caches.open(SHELL_CACHE).then((cache) => cache.put(url.pathname, copy)).catch(() => {}));
        }
        return response;
      }
      const shellCache = await caches.open(SHELL_CACHE);
      if (ALLOWED_SHELL_PATHS.has(url.pathname)) {
        const cached = await shellCache.match(url.pathname);
        if (cached) return cached;
      }
      return (await shellCache.match('/offline')) || new Response('Offline', { status: 503, headers: { 'Content-Type': 'text/plain' } });
    })());
    return;
  }

  if (ALLOWED_STATIC_PATHS.has(url.pathname)) {
    event.respondWith((async () => {
      const cache = await caches.open(STATIC_CACHE);
      const cached = await cache.match(url.pathname);
      if (cached) return cached;
      try {
        const response = await fetch(request);
        if (validResponse(response, url.pathname, 'static')) await cache.put(url.pathname, response.clone());
        return response;
      } catch {
        return new Response('', { status: 504 });
      }
    })());
  }
});
